pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address attacker) public {
        vm.assume(attacker != address(this));
        vm.assume(attacker != c.Owner());
        // Ensure we stay within reasonable balance bounds
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);

        // Fund the contract directly
        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 balanceBefore = address(c).balance;

        // Attacker attempts to withdraw
        vm.deal(attacker, amount);
        vm.prank(attacker);
        // Try withdrawal via low-level call to catch reverts for non-owner in correct version
        (bool success,) = address(c).call(abi.encodeWithSignature("withdraw()"));

        uint256 balanceAfter = address(c).balance;

        // If the call succeeded (as in buggy version), the balance should be drained
        // In correct version, the call reverts for non-owner, so balance should be unchanged
        // The invariant: if a non-owner calls withdraw(), either it reverts (balance unchanged)
        // or it succeeds and drains to Owner, but since attacker is not Owner, balance change
        // indicates a violation. In correct version, balanceBefore == balanceAfter always.
        // In buggy version, for some amount, balanceAfter == 0 && success == true.
        // We assert that balanceBefore == balanceAfter (correct behavior).
        assertEq(balanceBefore, balanceAfter, "Non-owner withdrawal changed balance");
    }
}

